//==================================================
//　UIResult - 결과창
//==================================================
//! runtextmacro 인터페이스("UIResult")
    private real time_passed
    boolean GAME_OFF
    boolean mastered
    integer xp_base
    integer xp_add
    integer xp_final
    integer cur_xp
    integer cur_level
    integer max_xp
    integer max_level

    UIResultChallenge chalWnd
    private InterfaceBackground sys_background
    private UICinematicMode sys_cinemode
    private UIResultBTNContinue btn_continue
    private UIResultBTNExit btn_exit
    private UIResultBTNChallenge btn_challenge
    private UIMileStone spr_milestone
    private UIGameModeLabel msg_mode
    private UIGameLevelLabel msg_level
    //! runtextmacro 인터페이스_장식물("msg_xpbase")
    //! runtextmacro 인터페이스_장식물("msg_xpadd")
    //! runtextmacro 인터페이스_장식물("msg_xpfinal")
    private InterfaceNumpad num_lv
    private InterfaceNumpad num_xp
    private InterfaceNumpad num_base
    private InterfaceNumpad num_add
    private InterfaceNumpad num_final
    private UIFactionPortraitSet infocard_faction
    private tick tick_refresher
    private static method onRefresh takes nothing returns nothing
        local thistype this = tick.getExpired().data
        local integer cur_base
        local integer cur_add
        local integer cur_final
        local integer xpcap
        set .time_passed = .time_passed + 0.04
        set cur_base = R2I(.xp_base * RMinBJ(1,time_passed/2))
        set cur_add = R2I(.xp_add * RMinBJ(1,RMaxBJ(0,(time_passed-2)/2)))
        set cur_final = R2I(.xp_final * RMinBJ(1,RMaxBJ(0,(time_passed-4)/2)))
        set .num_base.text = I2S(cur_base)
        set .num_add.text = I2S(cur_add)
        set .num_final.text = I2S(cur_final)
        if .mastered then
            set xpcap = FXGetMasterXpReq(.cur_level)
        else
            set xpcap = FXGetXpReq(.cur_level)
        endif
        set num_xp.text = I2S(.cur_xp) + "S" + I2S(xpcap)
        set num_lv.text = I2S(.cur_level)
        if .time_passed < 6 then
            return
        endif
        if .cur_level == .max_level then
            set xpcap = .max_xp
            set cur_xp = IMinBJ(.cur_xp+1000,xpcap)
        else
            set cur_xp = cur_xp + 1000
            if cur_xp < xpcap then
                return
            endif
            set cur_xp = 0
            set cur_level = cur_level + 1
        endif
    endmethod
    //! runtextmacro 인터페이스_이벤트()
        //! runtextmacro 인터페이스_이벤트_생성()
            local string path = ""
            local fxFaction myFax = FXGetPlayerCurrentFaction(.owner)
            
            set .GAME_OFF = false
            set .time_passed = 0
            set .mastered = false
            set .xp_base = 0
            set .xp_add = 0
            set .xp_final = 0
            set .cur_xp = 0
            set .cur_level = 0
            set .max_xp = 0
            set .max_level = 0
            
            set chalWnd = UIResultChallenge.create(this,.owner,0,0,0)
            
            set sys_background = InterfaceBackground.create(.owner)
            set sys_cinemode = UICinematicMode.create(this, .owner, 0, 0, 0 )
            
            set btn_continue = UIResultBTNContinue.create(this, .owner, 5440+64, -320.00, 1.00)
            set btn_exit = UIResultBTNExit.create(this, .owner, 5696+64, -320.00, 1.00 )
            set btn_challenge = UIResultBTNChallenge.create(this, .owner, 5952+64, -320.00, 1.00)
            if PANALTY_COUNT == 0 then
                call btn_challenge.enable(false)
            endif
            
            set spr_milestone = UIMileStone.create(this, .owner, 5408+64, 64.00-192.00, 0.00)
            
            set msg_mode = UIGameModeLabel.create(this, .owner, 5408, 384+32, 0.00)
            set msg_level = UIGameLevelLabel.create(this, .owner, 5408, 352-16, 0.00)
            //! runtextmacro 인터페이스_장식물_생성( "msg_xpbase", "'B01X'", "5408", "320-64", "0", "270", "1.5", "0" )
            //! runtextmacro 인터페이스_장식물_생성( "msg_xpadd", "'B01Y'", "5408", "320-64-96", "0", "270", "1.5", "0" )
            //! runtextmacro 인터페이스_장식물_생성( "msg_xpfinal", "'B01Z'", "5408", "320-64-192", "0", "270", "1.5", "0" )
            
            set infocard_faction = UIFactionPortraitSet.create(this, .owner, 6784, -320, 0)
            if WIN_MASTER[GetPlayerId(.owner)] then
                call spr_milestone.setState(1)
                call infocard_faction.setState( myFax + 100 )
                set path = "FXRD\\Numbers\\GoldNeon\\"
            else
                call spr_milestone.setState(0)
                call infocard_faction.setState( myFax )
                set path = "FXRD\\Numbers\\BlueNeon\\"
            endif
            set num_lv = InterfaceNumpad.create( .owner, 5424 + 64, 62.00-192.00, path, 0.50 )
            set num_xp = InterfaceNumpad.create( .owner, 5350 + 64, -64.00-192.00, path, 0.00 )
            set num_base = InterfaceNumpad.create( .owner, 5350 + 96, 16.00 + 192.00, path, 0.00 )
            set num_add = InterfaceNumpad.create( .owner, 5350 + 96, 16.00 + 96.00, path, 0.00 )
            set num_final = InterfaceNumpad.create( .owner, 5350 + 96, 16.00, path, 0.00 )
            
            set tick_refresher = tick.create(this)
        //! runtextmacro 인터페이스_이벤트_파괴()
            call tick_refresher.destroy()
            
            call num_lv.destroy()
            call num_xp.destroy()
            call num_base.destroy()
            call num_add.destroy()
            call num_final.destroy()
            
            call infocard_faction.destroy()
            
            call msg_mode.destroy()
            call msg_level.destroy()
            //! runtextmacro 인터페이스_장식물_파괴( "msg_xpbase" )
            //! runtextmacro 인터페이스_장식물_파괴( "msg_xpadd" )
            //! runtextmacro 인터페이스_장식물_파괴( "msg_xpfinal" )
            
            call spr_milestone.destroy()
            
            call btn_continue.destroy()
            call btn_exit.destroy()
            call btn_challenge.destroy()
            
            call sys_cinemode.destroy()
            call sys_background.destroy()
            
            call chalWnd.destroy()
            if not GAME_OFF then
                return
            endif
            if GetLocalPlayer() == .owner then
                call EndGame( true )
            endif
        //! runtextmacro 인터페이스_이벤트_보임()
            call sys_background.show(true)
            call sys_cinemode.show(true)
            
            call btn_continue.show(true)
            call btn_exit.show(true)
            call btn_challenge.show(true)
            
            call msg_mode.show(true)
            call msg_level.show(true)
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.msg_xpbase,true)
                call ShowDestructable(.msg_xpadd,true)
                call ShowDestructable(.msg_xpfinal,true)
            endif
            
            call spr_milestone.show(true)
            call infocard_faction.show(true)
            
            call tick_refresher.start(0.04,true,function thistype.onRefresh)
        //! runtextmacro 인터페이스_이벤트_숨김()
        //! runtextmacro 인터페이스_이벤트_활성화()
            call btn_continue.enable(true)
            call btn_exit.enable(true)
            call btn_challenge.enable(true)
        //! runtextmacro 인터페이스_이벤트_비활성화()
            call btn_continue.enable(false)
            call btn_exit.enable(false)
            call btn_challenge.enable(false)
//! runtextmacro 인터페이스_끝()
//==================================================
//　UIGameLevelLabel - 결과창에서 현재 난이도를 텍스트 라벨로 나타낸다.
//==================================================
//! runtextmacro 인터페이스("UIGameLevelLabel")
    private static integer array DEST_TYPE_ID
    //! runtextmacro 인터페이스_장식물("label")
    //! runtextmacro 인터페이스_이벤트()
        set DEST_TYPE_ID[1] = 'B01T'
        set DEST_TYPE_ID[2] = 'B01U'
        set DEST_TYPE_ID[3] = 'B01V'
        set DEST_TYPE_ID[4] = 'B01W'
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "label", "DEST_TYPE_ID[LEVEL_CURRENT]", "X", "Y", "Z", "270", "3.00", "0" )
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "label" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.label, true)
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.label, false)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
        //! runtextmacro 인터페이스_이벤트_비활성화()
//! runtextmacro 인터페이스_끝()
