//! runtextmacro 인터페이스("UIGameModeLabel")
    private static integer array DEST_TYPE_ID
    //! runtextmacro 인터페이스_장식물("label")
    //! runtextmacro 인터페이스_이벤트()
        set DEST_TYPE_ID[1] = 'B01P'
        set DEST_TYPE_ID[2] = 'B01Q'
        set DEST_TYPE_ID[3] = 'B01R'
        set DEST_TYPE_ID[4] = 'B01S'
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "label", "DEST_TYPE_ID[MODE_CURRENT]", "X", "Y", "Z", "270", "3.00", "0" )
