            //! runtextmacro 인터페이스_장식물_파괴( "label" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.label, true)
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.label, false)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
        //! runtextmacro 인터페이스_이벤트_비활성화()
//! runtextmacro 인터페이스_끝()
//==================================================
//　UIResultBTNContinue - 계속 진행
//==================================================
//! runtextmacro 인터페이스("UIResultBTNContinue")
    //! runtextmacro 인터페이스_장식물("dest")
    //! runtextmacro 인터페이스_유닛("bound")
    //! runtextmacro 인터페이스_이벤트()
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "dest", "'B01N'", "X", "Y", "Z", "270", "0.95", "0" )
            //! runtextmacro 인터페이스_유닛_생성( "bound", "'n001'", "X", "Y", "270" )
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "dest" )
            //! runtextmacro 인터페이스_유닛_파괴( "bound" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, true)
                if .enabled then
                    call SetUnitScale(.bound,0.95,0.95,1)
                else
                    call SetUnitScale(.bound,0,0,0)
                endif
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, false)
                call SetUnitScale(.bound,0,0,0)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
            call SetDestructableAnimation( .dest, "Stand" )
            if .visible then
                call SetUnitScale(.bound,0.95,0.95,1)
            endif
        //! runtextmacro 인터페이스_이벤트_비활성화()
            call SetDestructableAnimation( .dest, "Death" )
            call SetUnitScale(.bound,0,0,0)
        //! runtextmacro 인터페이스_이벤트_클릭("bound")
            local UIResult par = .parent
            call par.destroy()
//! runtextmacro 인터페이스_끝()
