//! runtextmacro 인터페이스("UIResultBTNExit")
    //! runtextmacro 인터페이스_장식물("dest")
    //! runtextmacro 인터페이스_유닛("bound")
    //! runtextmacro 인터페이스_이벤트()
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "dest", "'B01O'", "X", "Y", "Z", "270", "0.95", "0" )
            //! runtextmacro 인터페이스_유닛_생성( "bound", "'n003'", "X", "Y", "270" )
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "dest" )
            //! runtextmacro 인터페이스_유닛_파괴( "bound" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, true)
                if .enabled then
                    call SetUnitScale(.bound,0.95,0.95,1)
                else
                    call SetUnitScale(.bound,0,0,0)
                endif
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, false)
                call SetUnitScale(.bound,0,0,0)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
            call SetDestructableAnimation( .dest, "Stand" )
            if .visible then
                call SetUnitScale(.bound,0.95,0.95,1)
            endif
        //! runtextmacro 인터페이스_이벤트_비활성화()
            call SetDestructableAnimation( .dest, "Death" )
            call SetUnitScale(.bound,0,0,0)
        //! runtextmacro 인터페이스_이벤트_클릭("bound")
            local UIResult par = .parent
            local player p = .owner
            set par.GAME_OFF = true
            call par.destroy()
            set p = null
//! runtextmacro 인터페이스_끝()
//==================================================
//　UIResultBTNChallenge - 결과창 패널티 목록 확인 버튼
//==================================================
//! runtextmacro 인터페이스("UIResultBTNChallenge")
    //! runtextmacro 인터페이스_장식물("dest")
    //! runtextmacro 인터페이스_유닛("bound")
    //! runtextmacro 인터페이스_이벤트()
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "dest", "'B014'", "X", "Y", "Z", "270", "0.95", "0" )
            //! runtextmacro 인터페이스_유닛_생성( "bound", "'n005'", "X", "Y", "270" )
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "dest" )
            //! runtextmacro 인터페이스_유닛_파괴( "bound" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, true)
                if .enabled then
                    call SetUnitScale(.bound,0.95,0.95,1)
                else
                    call SetUnitScale(.bound,0,0,0)
                endif
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, false)
                call SetUnitScale(.bound,0,0,0)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
            call SetDestructableAnimation( .dest, "Stand" )
            if .visible then
                call SetUnitScale(.bound,0.95,0.95,1)
            endif
        //! runtextmacro 인터페이스_이벤트_비활성화()
            call SetDestructableAnimation( .dest, "Death" )
            call SetUnitScale(.bound,0,0,0)
        //! runtextmacro 인터페이스_이벤트_클릭("bound")
            local UIResult par = .parent
            call par.enable(false)
            call par.chalWnd.show(true)
//! runtextmacro 인터페이스_끝()

//===================================================
//　월드 초기화 작성 규칙
//===================================================
//! textmacro 월드_초기화_시작 takes NAME
scope WORLDINIT$NAME$ initializer main
    private function main takes nothing returns nothing
//! endtextmacro
//! textmacro 월드_초기화_끝
    endfunction
endscope
//! endtextmacro

//! runtextmacro 월드_초기화_시작("GAMETIME")
    //게임 시간 설정 : 시간이 흘러가지 않음 / 오후 12시로 고정
    call SuspendTimeOfDay( true )
    call SetFloatGameState( GAME_STATE_TIME_OF_DAY, 12.00 )
//! runtextmacro 월드_초기화_끝()

//! runtextmacro 월드_초기화_시작("LOADINGSCREEN")
    //카메라 적용
    call CameraSetupApplyForceDuration( gg_cam_ui_zone, true, 0.00 )
    call FixCameraForPlayer( GetLocalPlayer(), gg_cam_ui_zone )
    //화면 처리 : 암전 / 인터페이스 없음
    call EnableSelect( false, false )
    call EnableDragSelect( false, false )
    call ShowInterface( false, 0.00 )
    //부드러운 카메라 이동 지원
    call CameraSetSmoothingFactor( 0.50 )
    //시야 처리 : 모두 보이기
    call FogEnable( false )
    call FogMaskEnable( false )
    //기타 설정들
    //치트 메시지 숨기기
    call SetMapFlag(MAP_CHEATS_HIDDEN, true)
    //브금 개시
    call PlayMusic("Music\\YouAreMyKing_Part_A.mp3")
    call ResumeMusic()
    //인터페이스 영역 지형 투명하게 덧칠하기
    call SetTerrainType( 6144.00, 0.00, 'Oaby', 0, 8, 1 )
//! runtextmacro 월드_초기화_끝()

