    // TODO : 서번트 획득 이벤트에 대한 사용자 정의 액션 함수를 작성합니다.
        private function OnAnylevel takes nothing returns nothing
            call EVServantAttack.addFunction( eventServantAdd.e, function MeleeAttack )
            //Adding Special Skillz
            call FXRD_FXImmuneStun( eventServantAdd.e, true )
            call FXRD_FXImmuneKnockback( eventServantAdd.e, true )
            call ABILMashuBBuff.append( eventServantAdd.e, 1.00 )
            call ABILMashuCRest.append( eventServantAdd.e, 40.00 )
            call ABILMashuDLord.append( eventServantAdd.e )
            call UnitRemoveAbility(eventServantAdd.e, 'A0EJ')
        endfunction
        
