        if not IsUnitType( GetEnumUnit(), UNIT_TYPE_TAUREN ) then
            return
        endif
        if GetUnitLevel( GetEnumUnit() ) < LEV then
            return
        endif
        if GetUnitAbilityLevel( GetEnumUnit(), 'A09B' ) > 0 then
            if GetUnitAbilityLevel( GetEnumUnit(), 'A0D1' ) > 0 then
                return
            endif
        endif
        if GetUnitLevel( GetEnumUnit() ) > LEV then
            set LEV = GetUnitLevel( GetEnumUnit() )
            set CNT = 0
        endif
        if GetRandomInt( 0, CNT ) == 0 then
            set DEST = GetEnumUnit()
        endif
        set CNT = CNT + 1
    endmethod
