struct TLEnkiduEnuma extends array
    private tick main
    private unit caster
    private unit target
    private unit myDummy
    private static method onFire takes nothing returns nothing
        local thistype this = tick.getExpired()
        local integer enumatime = 10
        if IS_PLAYER_HAVE_EX_GILGAMESH[GetPlayerId(GetOwningPlayer(.caster))] then
            set enumatime = 15
        endif
        if IsUnitType(.target, UNIT_TYPE_DEAD) then
            call DestroyEffect(AddSpecialEffectTarget("Objects\\InventoryItems\\QuestionMark\\QuestionMark.mdl",.myDummy, "overhead" ) )
        else
            call BUFFEnkiduEnuma.apply( .target, .caster, 1.00, enumatime )
        endif
        set .myDummy = null
        set .caster = null
        set .target = null
        call .main.destroy()
    endmethod
    static method apply takes unit src, unit dst returns nothing
        local thistype this = tick.create(0)
        set .caster = src
        set .target = dst
        set .main = this
        set .myDummy = CreateUnit( Player(PLAYER_NEUTRAL_PASSIVE), 'o021', GetUnitX(src), GetUnitY(src), Angle.WBW(src,dst) )
        call SetUnitAnimation(.myDummy, "Spell One")
        call TLDummyLife.apply( .myDummy, 1.70 )
        call TLDummyFade.apply( .myDummy, 255, 255, 255, 0, 255, 255, 255, 128, 0.20 )
        call TLDummyFadespan.apply( .myDummy, 255, 255, 255, 128, 0, 0, 0, 0, 1.40,1.60)
        call .main.start( 0.30, true, function thistype.onFire )
    endmethod
endstruct

