//! runtextmacro 어빌리티_선언_개시("JeanneFire")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_추가타()
    private tick MarkTick
    private effect MarkFx
    private unit MarkedTarget
    private real MarkDamage
    private static method enumFunction takes nothing returns nothing
        local thistype this = tick.getExpired().data
        if IsUnitDead( .source ) then
            return
        endif
        if IsUnitDead( .MarkedTarget ) then
            if .MarkFx != null then
                call DestroyEffect(.MarkFx)
                set .MarkFx = null
            endif
            set .MarkedTarget = null
            return
        endif
        call DestroyEffect(AddSpecialEffectTarget("Objects\\Spawnmodels\\Other\\NeutralBuildingExplosion\\NeutralBuildingExplosion.mdl",.MarkedTarget,"origin"))
        call enemy.dealLogicEx( .source, .MarkedTarget, .MarkDamage, true, true, WEAPON_TYPE_WHOKNOWS, 1 )
    endmethod
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득()
        set .MarkedTarget = null
        set .MarkFx = null
        set .MarkDamage = 0.0
        set .MarkTick = tick.create(this)
        call .MarkTick.start( 1.0, true, function thistype.enumFunction )
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_잃음()
        if .MarkFx != null then
            call DestroyEffect(.MarkFx)
            set .MarkFx = null
        endif
        set .MarkedTarget = null
        call .MarkTick.destroy()
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        local unit src = GetTriggerUnit()
        local unit dst = GetEventDamageSource()
        if IsUnitType(dst,UNIT_TYPE_GIANT) then
            if .MarkedTarget != dst then
                if .MarkFx != null then
                    call DestroyEffect(.MarkFx)
                    set .MarkFx = null
                endif
                set .MarkedTarget = dst
                set .MarkDamage = 0.0
                set .MarkFx = AddSpecialEffectTarget("Doodads\\Cinematic\\FirePillarMedium\\FirePillarMedium.mdl",dst,"chest")
            endif
            set .MarkDamage = .MarkDamage + 250.0
        endif
        set src = null
        set dst = null
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()

//! runtextmacro 어빌리티_선언_개시("JeanneCARI")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_패시브_쿨타임_일정()
    // 사용자 정의 멤버
    private static unit DEST = null
    private static integer CNT = 0
    private static integer LEV = 0
    private static method enumGetTarget takes nothing returns nothing
        if not IsUnitType( GetEnumUnit(), UNIT_TYPE_TAUREN ) then
            return
        endif
        if GetUnitAbilityLevel( GetEnumUnit(), 'B01C' ) > 0 then
            return
        endif
        if GetUnitLevel( GetEnumUnit() ) > LEV then
            set LEV = GetUnitLevel( GetEnumUnit() )
            set CNT = 0
        endif
        if GetRandomInt( 0, CNT ) == 0 then
            set DEST = GetEnumUnit()
        endif
        set CNT = CNT + 1
    endmethod
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득_잃음_없음()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        local integer i = 0
        set DEST = null
        set CNT = 0
        set LEV = 0
        call splash.range( splash.PLAYER, .source, GetUnitX(.source), GetUnitY(.source), 1000.0, function thistype.enumGetTarget )
        if DEST == null then
            return
        endif
        call DestroyEffect(AddSpecialEffectTarget("Abilities\\Spells\\Human\\Resurrect\\ResurrectTarget.mdl",DEST,"origin"))
        //call DestroyEffect(AddSpecialEffectTarget("Abilities\\Spells\\Human\\DispelMagic\\DispelMagicTarget.mdl",.source,"origin"))
        call BUFFJeanneCARI.apply( DEST, 10.0 )
        set DEST = null
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()

//! runtextmacro 버프_선언_개시("JeanneCARI")
    private static constant integer ABID = 'A0GJ'
    private static constant integer BFID = 'B01C'
    private static constant integer ATBO = 30
    // TODO : 버프의 종류를 선언합니다.
    //! runtextmacro 버프_종류_기간제()
    // TODO : 버프의 종류에 대응되는 각 버프 이벤트를 작성합니다.
    private static constant string PATH_EFFECT = "Abilities\\Spells\\Human\\DivineShield\\DivineShieldTarget.mdl"
    private static constant string POINT_EFFECT = "origin"
    private effect fx
    //! runtextmacro 버프_이벤트_버프_부여됨()
        set .fx = AddSpecialEffectTarget(PATH_EFFECT,.source,POINT_EFFECT)
        call UnitAddAbility(.source, ABID)
        call EVDamageManager.addBonus( .source, ATBO )
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_갱신됨()
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_해제됨()
        if IsUnitAlive(.source) then
            call UnitRemoveAbility(.source, ABID)
            call UnitRemoveAbility(.source, BFID)
            call EVDamageManager.addBonus( .source, -ATBO )
        endif
        call DestroyEffect(.fx)
        set .fx = null
    //! runtextmacro 버프_이벤트_끝()
//! runtextmacro 버프_선언_끝()

