//! runtextmacro 버프_선언_개시("CCC")
    // TODO : 버프의 종류를 선언합니다.
    //! runtextmacro 버프_종류_반복적_중첩안됨()
    // TODO : 버프의 종류에 대응되는 각 버프 이벤트를 작성합니다.
    static constant integer ABILITY = 'A0DM'
    static constant integer BUFF = 'B00N'
    private effect fx
    private real damage
    //! runtextmacro 버프_이벤트_버프_부여됨()
        set .damage = 0
        set .fx = AddSpecialEffectTarget("Abilities\\Spells\\Undead\\Possession\\PossessionCaster.mdl", .source, "origin")
        call UnitAddAbility(.source, ABILITY)
    //! runtextmacro 버프_이벤트_끝()
    private static real ENUM_DAMAGE
    private static method EnumKiara takes nothing returns nothing
        call DestroyEffect(AddSpecialEffectTarget("Abilities\\Weapons\\SludgeMissile\\SludgeMissile.mdl", GetEnumUnit(), "chest"))
        call EVDebuffSlow.apply( GetEnumUnit(), 1.00 )
        call enemy.dealLogicEx( splash.src, GetEnumUnit(), ENUM_DAMAGE, true, false, WEAPON_TYPE_METAL_HEAVY_BASH, 1 )
    endmethod
    //! runtextmacro 버프_이벤트_버프_반복됨()
        if IsUnitDead(.caster) then
            return
        endif
        set .damage = .damage + 100
        set ENUM_DAMAGE = .damage
        call splash.range( splash.ENEMY, .caster, GetUnitX(.source), GetUnitY(.source), 700, function thistype.EnumKiara )
        call KillUnit(CreateUnit(Player(15),'o02A',GetUnitX(.source),GetUnitY(.source),GetRandomReal(0.00,360.00)))
        call DestroyEffect(AddSpecialEffectTarget("Abilities\\Spells\\Demon\\DemonBoltImpact\\DemonBoltImpact.mdl", .source, "origin"))
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_갱신됨()
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_해제됨()
        if not IsUnitDead(.source) then
            call UnitRemoveAbility(.source, ABILITY)
            call UnitRemoveAbility(.source, BUFF)
        endif
        call DestroyEffect(.fx)
        set .fx = null
    //! runtextmacro 버프_이벤트_끝()
//! runtextmacro 버프_선언_끝()

struct FXKiara extends array
    private tick main
    private unit caster
    private effect myFx
    private integer loops
    private static method onFinal takes nothing returns nothing
        local thistype this = tick.getExpired()
        call DestroyEffect(.myFx)
        set .myFx = null
        set .caster = null
        call .main.destroy()
    endmethod
    private static method onFire takes nothing returns nothing
        local thistype this = tick.getExpired()
        if not IsUnitType(.caster, UNIT_TYPE_DEAD) then
            call ShowUnit(.caster, true)
        endif
        call .main.start( 3.00, true, function thistype.onFinal )
    endmethod
    static method cast takes unit src returns nothing
        local thistype this = tick.create(0)
        call EVDebuffStunServant.apply( src, 4.00 )
        call ShowUnit(src, false)
        call SetSoundPosition(gg_snd_servant_spawn_rare, GetUnitX(src), GetUnitY(src),300)
        call StartSound(gg_snd_servant_spawn_rare)
        set .myFx = AddSpecialEffect("FX\\BB\\CCC.mdl",GetUnitX(src),GetUnitY(src) )
        call DestroyEffect(AddSpecialEffect("Abilities\\Spells\\Human\\FlameStrike\\FlameStrikeTarget.mdl",GetUnitX(src),GetUnitY(src) ))
        //call KillUnit(CreateUnit(Player(15),'o00M',GetUnitX(src),GetUnitY(src),270))
        set .caster = src
        set .main = this
        call .main.start( 3.00, true, function thistype.onFire )
    endmethod
endstruct

