    // TODO : 서번트 무기에 관한 함수를 Import하거나, 사용자 정의 함수를 작성합니다.
        private function SummerWeapon takes nothing returns nothing
            local unit source = GetTriggerUnit()
            local unit target = GetEventDamageSource()
            local real mtpl = 1.00
            if GetRandomReal(0.00,100.00) < 15.00 then
                if GetUnitAbilityLevel( source, 'A0FI' ) > 0 then
                    set mtpl = 10.50
                    call SetUnitState( source, UNIT_STATE_MANA, GetUnitState( source, UNIT_STATE_MANA ) + 15 )
                else
                    set mtpl = 7.00
                    call SetUnitState( source, UNIT_STATE_MANA, GetUnitState( source, UNIT_STATE_MANA ) + 10 )
                endif
                call DestroyEffect(AddSpecialEffectTarget("FX Slash Cross Red\\lianzhan.mdl",target,"origin"))
            else
                call SetUnitState( source, UNIT_STATE_MANA, GetUnitState( source, UNIT_STATE_MANA ) + 5 )
            endif
            call enemy.dealLogic( source, target, EVDamageManager.getFinalDamage(source) * mtpl, WEAPON_TYPE_WHOKNOWS, 1 )
            set source = null
            set target = null
        endfunction

