//　서번트 연출
//==================================================================
struct CMSSVoidAntiSeraph extends array
    private tick main
    private unit caster
    private real damage
    private static method onFinal takes nothing returns nothing
        local thistype this = tick.getExpired()
        set .caster = null
        call .main.destroy()
    endmethod
    private static method enumDealt takes nothing returns nothing
        local thistype this = tick.getExpired()
        call DestroyEffect(AddSpecialEffectTarget("Abilities\\Weapons\\FarseerMissile\\FarseerMissile.mdl",GetEnumUnit(),"chest"))
        if not IsUnitType(GetEnumUnit(),UNIT_TYPE_GIANT) then
            call FXRD_FXDebuffShock( GetEnumUnit(), 1.00 )
            call EVDebuffSlow.apply( GetEnumUnit(), 3.00 )
        endif
        call enemy.dealLogicEx( .caster, GetEnumUnit(), .damage, true, true, WEAPON_TYPE_METAL_MEDIUM_BASH, 1 )
    endmethod
    private static method onFire takes nothing returns nothing
        local thistype this = tick.getExpired()
        if IsUnitAlive(.caster) then
            call KillUnit( CreateUnit( Player(PLAYER_NEUTRAL_PASSIVE), 'o02B', GetUnitX(.caster), GetUnitY(.caster), 270.0 ) )
            call KillUnit( CreateUnit( Player(PLAYER_NEUTRAL_PASSIVE), 'o01F', GetUnitX(.caster), GetUnitY(.caster), 270.0 ) )
            call splash.range( splash.ENEMY, .caster, GetUnitX(.caster), GetUnitY(.caster), 1000.0, function thistype.enumDealt )
        endif
        call .main.start( 0.20, false, function thistype.onFinal )
    endmethod
    static method cast takes unit src, real dmg returns nothing
        local thistype this = tick.create(0)
        set .main = this
        set .caster = src
        set .damage = dmg
        call .main.start( 1.00, true, function thistype.onFire )
    endmethod
endstruct

