    // 사용자 정의 멤버
    private static unit DEST = null
    private static integer CNT = 0
    private static integer LEV = 0
    private static method enumGetTarget takes nothing returns nothing
        if not IsUnitType( GetEnumUnit(), UNIT_TYPE_TAUREN ) then
            return
        endif
        if GetUnitLevel( GetEnumUnit() ) < LEV then
            return
        endif
        if GetUnitAbilityLevel( GetEnumUnit(), 'BPSE' ) == 0 then
            return
        endif
        if GetUnitLevel( GetEnumUnit() ) > LEV then
            set LEV = GetUnitLevel( GetEnumUnit() )
            set CNT = 0
        endif
        if GetRandomInt( 0, CNT ) == 0 then
            set DEST = GetEnumUnit()
        endif
        set CNT = CNT + 1
    endmethod
