    private static method EnumShock takes nothing returns nothing
        //call FXRD_FXDebuffShock( GetEnumUnit(), 1.0 )
        call EVDebuffSlow.apply( GetEnumUnit(), 2.0 )
        call enemy.dealLogic( GetTriggerUnit(), GetEnumUnit(), EVDamageManager.getFinalDamage( GetTriggerUnit() ) * 0.25, WEAPON_TYPE_WHOKNOWS, 1 )
