        local unit source = GetTriggerUnit()
        local unit target = GetEventDamageSource()
        local real punchBonus
        local real x = GetUnitX(source) + Polar.X(250.0,GetUnitFacing(source))
        local real y = GetUnitY(source) + Polar.Y(250.0,GetUnitFacing(source))
        if IsUnitType(target,UNIT_TYPE_GIANT) then
            if .LastAttackWasGiant != true then
                set .LastAttackWasGiant = true
                call AddUnitAnimationProperties(source,"alternate",true)
                call SetUnitAnimation(source,"attack alternate")
            endif
            set punchBonus = 1.7 + 0.1 * GetUnitAbilityLevel(.source,'A0H7')
            call FXRD_FXDebuffShock( target, 1.0 )
            call EVDebuffSlow.apply( target, 3.0 )
            call enemy.dealLogicEx( source, target, EVDamageManager.getFinalDamage( source ) * punchBonus, true, true, WEAPON_TYPE_METAL_HEAVY_BASH, 1 )
        else
            if .LastAttackWasGiant != false then
                set .LastAttackWasGiant = false
                call AddUnitAnimationProperties(source,"alternate",false)
                call SetUnitAnimation(source,"attack")
            endif
            call DestroyEffect(AddSpecialEffect("FX\\ElizabethAlter\\Wave.mdl",x,y))
            call DestroyEffect(AddSpecialEffect("Abilities\\Spells\\Human\\Thunderclap\\ThunderClapCaster.mdl",x,y))
            call DestroyEffect(AddSpecialEffectTarget("Abilities\\Weapons\\MeatwagonMissile\\MeatwagonMissile.mdl",target,"chest"))
            call enemy.dealLogicEx( source, target, 99999999.0, true, false, WEAPON_TYPE_WHOKNOWS, 1 )
            call splash.range( splash.ENEMY, source, x, y, 750.0, function thistype.EnumShock )
            call KillUnit(CreateUnit(FX_PLAYER_DUMMY,'o01E',x, y,GetRandomReal(0.0,360.0)))
        endif
        set source = null
        set target = null
