        local integer playerGiants = 0
        local real scale
        local integer sizeLevel
        set playerGiants = playerGiants + GetPlayerUnitTypeCount(GetOwningPlayer(.source),'-SAX') /*또 다른 킹프로테아*/
        set playerGiants = playerGiants + GetPlayerUnitTypeCount(GetOwningPlayer(.source),'-ALX') /*거신 알테라*/
