        set scale = 0.8 + .PrevBonus * 0.0002
        call SetUnitScale(.source,scale,scale,scale)
        set sizeLevel = 1 + ( .PrevBonus / 200 )
        call SetUnitAbilityLevel(.source,'A0H7',IMinBJ(10,sizeLevel))
