//! runtextmacro 어빌리티_선언_개시("EXGawainNightless")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_액티브("A0HR")
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득_잃음_없음()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        call DisplayTextToPlayer(GetLocalPlayer(),0.0,0.0,pcs.get(GetOwningPlayer(GetSpellAbilityUnit()))+"|r님이 SE.RA.PH의 시간을 |c00b0b0b0AM 09:00|r 으로 되돌립니다!")
        call SetFloatGameState(GAME_STATE_TIME_OF_DAY,8.99)
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()
//! runtextmacro 어빌리티_선언_개시("EXGawainAttack")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_추가타()
        private static string array MESSAGE
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득()
        set MESSAGE[0] = "|c00FF4040세잇!|r"
        set MESSAGE[1] = "|c00FF4040훗!|r"
        set MESSAGE[2] = "|c00FF4040핫!|r"
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_잃음()
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        local unit source = GetTriggerUnit()
        local unit target = GetEventDamageSource()
        local boolean isDayTime = GetUnitAbilityLevel(source,'A0HN') > 0
        local real mana = 5.0
        local real curMana
        if isDayTime then
            call DestroyEffect(AddSpecialEffectTarget("FX Power Charge\\FX Power Charge Blue.mdl",source,"hand right"))
            call DestroyEffect(AddSpecialEffectTarget("FX\\Gawain\\Sun.mdl",target,"origin"))
            set mana = 15.0
        else
            call bountyTag.custom( GetOwningPlayer(source), GetUnitX(source)+GetRandomReal(-64.0,64.0), GetUnitY(source)+64, MESSAGE[GetRandomInt(0,2)] )
        endif
        set curMana = GetUnitState( source, UNIT_STATE_MANA ) + mana
        if curMana >= 300.0 then
            if isDayTime then
                call TMGawainGalatin.cast( source, target, EVDamageManager.getFinalDamage( source ) * 30.0 )
            else
                call TMGawainGalatin.cast( source, target, EVDamageManager.getFinalDamage( source ) * 10.0 )
            endif
            set curMana = 0
        endif
        call SetUnitState( source, UNIT_STATE_MANA, curMana )
        
        call enemy.dealLogic( source, target, EVDamageManager.getFinalDamage( source ), WEAPON_TYPE_WHOKNOWS, 1 )
        set source = null
        set target = null
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()

//! runtextmacro 어빌리티_선언_개시("EXGawainSunPower")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_패시브_쿨타임_일정()
        private boolean WasAlternate
        private integer PrevBonus
        private effect SunAura
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득()
        set .PrevBonus = 0
        set .WasAlternate = false
        set .SunAura = null
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_잃음()
        if .SunAura != null then
            call DestroyEffect(.SunAura)
            set .SunAura = null
        endif
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        local real time = GetFloatGameState(GAME_STATE_TIME_OF_DAY)
        local boolean isBonus = (9.0 < time and time < 12.0) or (15.0 < time and time < 18.0)
        call EVDamageManager.addBonus( .source, -.PrevBonus )
        set .PrevBonus = 0
        if not isBonus then
            if not .WasAlternate then
                set .WasAlternate = true
                call AddUnitAnimationProperties(.source,"alternate",true)
            endif
            if .SunAura != null then
                call DestroyEffect(.SunAura)
                set .SunAura = null
            endif
            if not IsUnitDead(.source) then
                call SetUnitAbilityLevel(.source,'A0HM',1)
                call SetUnitAbilityLevel(.source,'A0HO',1)
                call SetUnitAbilityLevel(.source,'A0HP',1)
            endif
            return
        endif
        if .WasAlternate then
            set .WasAlternate = false
            call AddUnitAnimationProperties(.source,"alternate",false)
        endif
        if .SunAura == null then
            set .SunAura = AddSpecialEffectTarget("FXRD\\FX\\GoldTimer\\GoldTimer.mdl",.source,"origin")
        endif
        if not IsUnitDead(.source) then
            call SetUnitAbilityLevel(.source,'A0HM',2)
            call SetUnitAbilityLevel(.source,'A0HO',2)
            call SetUnitAbilityLevel(.source,'A0HP',2)
        endif
        set .PrevBonus = 200
        call EVDamageManager.addBonus( .source, .PrevBonus )
        call BUFFEXGawainDayTime.apply( .source, 2.0 )
        call FXRD_FXImmuneStunTimed( .source, 2.0 )
        call FXRD_FXImmuneKnockbackTimed( .source, 2.0 )
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()

//! runtextmacro 어빌리티_선언_개시("EXGawainBestilac")
    // TODO : 어빌리티의 종류를 선언합니다.
    //! runtextmacro 어빌리티_종류_패시브_쿨타임_일정()
    // TODO : 어빌리티의 종류에 대응되는 각 어빌리티 이벤트를 작성합니다.
    //! runtextmacro 어빌리티_이벤트_어빌리티_습득()
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_잃음()
    //! runtextmacro 어빌리티_이벤트_끝()
    //! runtextmacro 어빌리티_이벤트_어빌리티_효과_시작()
        local boolean isDayTime = GetUnitAbilityLevel(source,'A0HN') > 0
        local real mana = 2.0
        if isDayTime then
            call DestroyEffect(AddSpecialEffectTarget("Abilities\\Spells\\Items\\AIma\\AImaTarget.mdl",.source,"origin"))
            set mana = 6.0
        endif
        call SetUnitState( source, UNIT_STATE_MANA, GetUnitState( source, UNIT_STATE_MANA ) + mana )
    //! runtextmacro 어빌리티_이벤트_끝()
//! runtextmacro 어빌리티_선언_끝()
