//　서번트 버프
//==================================================================
//! runtextmacro 버프_선언_개시("EXGawainDayTime")
    // TODO : 버프의 종류를 선언합니다.
    //! runtextmacro 버프_종류_기간제()
    // TODO : 버프의 종류에 대응되는 각 버프 이벤트를 작성합니다.
    static constant integer ABILITY = 'A0HN'
    static constant integer BUFF = 'B01L'
    //private static constant integer ATBO = 200
    //private effect fx1
    //private effect fx2
    //! runtextmacro 버프_이벤트_버프_부여됨()
        //set .fx1 = AddSpecialEffectTarget("Abilities\\Spells\\Orc\\Bloodlust\\BloodlustTarget.mdl",.source,"hand left")
        //set .fx2 = AddSpecialEffectTarget("Abilities\\Spells\\Orc\\Bloodlust\\BloodlustSpecial.mdl",.source,"hand right")
        call UnitAddAbility(.source, ABILITY)
        //call EVDamageManager.addBonus( .source, ATBO )
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_갱신됨()
    //! runtextmacro 버프_이벤트_끝()
    //! runtextmacro 버프_이벤트_버프_해제됨()
        if not IsUnitDead(.source) then
            //call EVDamageManager.addBonus( .source, -ATBO )
            call UnitRemoveAbility(.source, ABILITY)
            call UnitRemoveAbility(.source, BUFF)
        endif
        //call DestroyEffect(.fx1)
        //call DestroyEffect(.fx2)
        //set .fx1 = null
        //set .fx2 = null
    //! runtextmacro 버프_이벤트_끝()
//! runtextmacro 버프_선언_끝()
struct TMGawainGalatin
    private timer mainFlow
    private unit caster
    private unit target
    private unit dummy
    private real X
    private real Y
    private real damage
    private static method EnumEnhanced takes nothing returns nothing
        local thistype this = GetHandleUserData(GetExpiredTimer())
        call FXRD_FXDebuffShock( GetEnumUnit(), 5.0 )
        call enemy.dealLogicEx( .caster, GetEnumUnit(), .damage, true, true, WEAPON_TYPE_METAL_HEAVY_BASH, 1 )
    endmethod
    private static method EnumHit takes nothing returns nothing
        local thistype this = GetHandleUserData(GetExpiredTimer())
        call enemy.dealLogic( .caster, GetEnumUnit(), .damage, WEAPON_TYPE_METAL_HEAVY_BASH, 1 )
    endmethod
    private static method onFire takes nothing returns nothing
        local thistype this = GetHandleUserData(GetExpiredTimer())
        local boolean isDayTime = GetUnitAbilityLevel(.caster,'A0HN') > 0
        if not IsUnitDead( .caster ) then
            call KillUnit(CreateUnit(FX_PLAYER_DUMMY,'o02P',.X,.Y,GetRandomReal(0.0,270.0)))
            if isDayTime then
                call KillUnit(CreateUnit(FX_PLAYER_DUMMY,'o02P',.X,.Y,GetRandomReal(0.0,270.0)))
                call KillUnit(CreateUnit(FX_PLAYER_DUMMY,'o02P',.X,.Y,GetRandomReal(0.0,270.0)))
                call splash.range( splash.ENEMY, .caster, .X,.Y, 350.0, function thistype.EnumEnhanced )
            else
                call splash.range( splash.ENEMY, .caster, .X,.Y, 350.0, function thistype.EnumHit )
            endif
        endif
        call ClearHandleUserData(.mainFlow)
        call DestroyTimer(.mainFlow)
        set .mainFlow = null
        call KillUnit(.dummy)
        set .dummy = null
        set .caster = null
        set .target = null
    endmethod
    private static method onCharge takes nothing returns nothing
        local thistype this = GetHandleUserData(GetExpiredTimer())
        set .dummy = CreateUnit(FX_PLAYER_DUMMY,'o02Q',.X,.Y,270.0)
        call SetUnitAnimation(.dummy,"birth")
        call TimerStart(.mainFlow,0.5,false,function thistype.onFire)
    endmethod
    static method cast takes unit src, unit dst, real dmg returns nothing
        local thistype this = create()
        set .caster = src
        set .target = dst
        set .damage = dmg
        set .X = GetUnitX(dst)
        set .Y = GetUnitY(dst)
        set .mainFlow = CreateTimer()
        call SetHandleUserData(.mainFlow,this)
        call TimerStart(.mainFlow,0.03125,false,function thistype.onCharge)
    endmethod
endstruct

