    function FXSetFaction$TYPE$ takes fxFaction f, $VTYPE$ v returns nothing
        set $VRNAME$[f] = v
    endfunction
    function FXGetFaction$TYPE$ takes fxFaction f returns $VTYPE$
        return $VRNAME$[f]
    endfunction
