    endglobals
    struct fxFaction extends array
    endstruct
    function FXCreateFaction takes integer index returns nothing
        set FACTION_EXISTS[index] = true
        if FX_FACTION_MAX < index then
            set FX_FACTION_MAX = index
        endif
    endfunction
