            //마스터 일러스트 +100
            set PORT_TYPE_ID[101] = 'B00N'
            set PORT_TYPE_ID[102] = 'B005'
            set PORT_TYPE_ID[103] = 'B00O'
            set PORT_TYPE_ID[104] = 'B00Q'
            
            set LABEL_TYPE_ID[1] = 'B00S'
            set LABEL_TYPE_ID[2] = 'B00A'
            set LABEL_TYPE_ID[3] = 'B00T'
            set LABEL_TYPE_ID[4] = 'B00U'
        //! runtextmacro 인터페이스_이벤트_생성()
            set .port = null
            set .icon = null
            set .label = null
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "port" )
            //! runtextmacro 인터페이스_장식물_파괴( "icon" )
            //! runtextmacro 인터페이스_장식물_파괴( "label" )
        //! runtextmacro 인터페이스_이벤트_보임()
            local boolean isMastered = .state > 99
            local string labelAction = ANI_STAND
            if isMastered then
                set labelAction = ANI_DEATH
            endif
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.port, true)
                call SetDestructableAnimation( .port, ANI_BIRTH )
                call ShowDestructable(.label, true)
                call SetDestructableAnimation( .label, labelAction )
                call ShowDestructable(.icon, true)
                call SetDestructableAnimation( .icon, ANI_WALK )
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.port, false)
                call ShowDestructable(.label, false)
                call ShowDestructable(.icon, false)
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
        //! runtextmacro 인터페이스_이벤트_비활성화()
        //! runtextmacro 인터페이스_이벤트_상태_변경("newState")
            local integer newIcoState = ModuloInteger(newState,100)
            call RemoveDestructable(.port)
            call RemoveDestructable(.icon)
            call RemoveDestructable(.label)
            //! runtextmacro 인터페이스_장식물_생성( "port", "PORT_TYPE_ID[newState]", "X", "Y", "Z+2.00", "270", "8.00", "0" )
            //! runtextmacro 인터페이스_장식물_생성( "icon", "ICON_TYPE_ID[newIcoState]", "X+128", "Y", "Z+1.00", "270", "8.00", "0" )
            //! runtextmacro 인터페이스_장식물_생성( "label", "LABEL_TYPE_ID[newIcoState]", "X+222", "Y-32", "Z+3.00", "270", "2.00", "0" )
//! runtextmacro 인터페이스_끝()

//==================================================
//　UIMileStone - 금장/레벨 표시기
//　　이 UI의 state는 다음을 의미합니다.
//　　　0 = 금장 아님
//　　　1 = 금장
//　　　2 = 금장 아님 경고
//　　　3 = 금장 경고
//==================================================
//! runtextmacro 인터페이스("UIMileStone")
    private static string array ANI_LIST
    //! runtextmacro 인터페이스_장식물("dest")
    //! runtextmacro 인터페이스_이벤트()
            set ANI_LIST[0] = "Stand"
            set ANI_LIST[1] = "Death"
            set ANI_LIST[2] = "Birth"
            set ANI_LIST[3] = "Decay"
        //! runtextmacro 인터페이스_이벤트_생성()
            //! runtextmacro 인터페이스_장식물_생성( "dest", "'B007'", "X", "Y", "Z", "270", "1.50", "0" )
        //! runtextmacro 인터페이스_이벤트_파괴()
            //! runtextmacro 인터페이스_장식물_파괴( "dest" )
        //! runtextmacro 인터페이스_이벤트_보임()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, true)
            endif
        //! runtextmacro 인터페이스_이벤트_숨김()
            if GetLocalPlayer() == .owner then
                call ShowDestructable(.dest, false)
            endif
        //! runtextmacro 인터페이스_이벤트_상태_변경("newState")
            call SetDestructableAnimation( .dest, ANI_LIST[newState] )
        //! runtextmacro 인터페이스_이벤트_활성화()
        //! runtextmacro 인터페이스_이벤트_비활성화()
//! runtextmacro 인터페이스_끝()

//==================================================
//==================================================
//! runtextmacro 인터페이스("UICinematicMode")
    //! runtextmacro 인터페이스_이벤트()
        //! runtextmacro 인터페이스_이벤트_생성()
        //! runtextmacro 인터페이스_이벤트_파괴()
            call .show(false)
        //! runtextmacro 인터페이스_이벤트_보임()
            //현황판 최소화(화면 덜 가리기)
            call statusBoard.super.minimizeForPlayer( .owner, true )
            //카메라 고정
            call EnableSmartSeeyaForPlayer( .owner, false )
            if GetLocalPlayer() == .owner then
                call CameraSetupApplyForceDuration( gg_cam_ui_zone, true, 0.00 )
                call EnableDragSelect(false, false)
            endif
            call FixCameraForPlayer( .owner, gg_cam_ui_zone )
        //! runtextmacro 인터페이스_이벤트_숨김()
            //카메라 고정 해제
            call FixCameraForPlayer( .owner, null )
            call EnableSmartSeeyaForPlayer( .owner, true )
            if GetLocalPlayer() == .owner then
                call EnableDragSelect(true, true)
                call ResetToGameCamera( 0.00 )
                call PanCameraToTimed( GetPlayerStartLocationX(.owner), GetPlayerStartLocationY(.owner), 0.00 )
            endif
        //! runtextmacro 인터페이스_이벤트_활성화()
        //! runtextmacro 인터페이스_이벤트_비활성화()
//! runtextmacro 인터페이스_끝()

//! textmacro TypeId takes NAME
    struct $NAME$TypeId
        private static hashtable H = InitHashtable()
        static method convert takes integer id returns integer
            local thistype this
            if HaveSavedInteger( H, 0, id ) then
                return LoadInteger( H, 0, id )
            endif
            set this = thistype.allocate(  )
            call SaveInteger( H, 0, id, this )
            return this
        endmethod
        static method get takes integer id returns integer
            if HaveSavedInteger( H, 0, id ) then
                return LoadInteger( H, 0, id )
            endif
            return 0
        endmethod
    endstruct
//! endtextmacro

library TypeId
    //! runtextmacro TypeId( "Unit" )
    //! runtextmacro TypeId( "Ability" )
    //! runtextmacro TypeId( "Research" )
    //! runtextmacro TypeId( "Issue" )
endlibrary
